{"command": "cd $WORKSPACE_DIR/work && python3 - <<'EOF'
import re
src=open("build.py").read().split("# ================================================================ DOCUMENT")[0]
ns={}; exec(src, ns)
cid = {r[0] for r in ns['C']}
rid = {r[0] for r in ns['E']}
def refs(text):
    return set(re.findall(r'\bC-\d{2}\b', text)), set(re.findall(r'\bR-\d{2}\b', text))
missing_c=set(); missing_r=set()
for coll in ['A','B','C','E','G','H','I_QUESTIONS']:
    for row in ns[coll]:
        for cell in row:
            c,r = refs(str(cell))
            missing_c |= (c - cid); missing_r |= (r - rid)
print("undefined C refs:", sorted(missing_c))
print("undefined R refs:", sorted(missing_r))
# conditions referenced
conds=set()
for coll in ['C','E','H']:
    for row in ns[coll]:
        for cell in row:
            for m in re.findall(r'Cond(?:s)?\.?\s*(\d{1,2})', str(cell)):
                conds.add(int(m))
print("condition numbers referenced outside valid range:", sorted(c for c in conds if c<1 or c>35))
# which C ids are never referenced anywhere (excluding C-defs themselves)?
alltext=" ".join(" ".join(str(x) for x in row) for coll in ['A','B','E','H'] for row in ns[coll])
unused=[c for c in sorted(cid) if c not in alltext]
print("C-ids not cross-referenced from A/B/E/H:", unused)
EOF"}

