{"command": "cd $WORKSPACE_DIR/work && python3 - <<'EOF'
p='build.py'; s=open(p).read()
old = '''def set_widths(table, widths):
    fixed_layout(table)
    table.autofit = False
    for row in table.rows:
        for i, w in enumerate(widths):
            if i < len(row.cells):
                row.cells[i].width = Inches(w)'''
new = '''def set_widths(table, widths):
    fixed_layout(table)
    table.autofit = False
    for row in table.rows:
        for i, w in enumerate(widths):
            if i < len(row.cells):
                row.cells[i].width = Inches(w)
    # keep tblGrid and tblW in step with the cell widths, otherwise Word/LibreOffice fall back to an equal grid
    grid = table._tbl.find(qn('w:tblGrid'))
    if grid is not None:
        for gc, w in zip(grid.findall(qn('w:gridCol')), widths):
            gc.set(qn('w:w'), str(int(w * 1440)))
    tblPr = table._tbl.find(qn('w:tblPr'))
    tblW = tblPr.find(qn('w:tblW')) if tblPr is not None else None
    if tblW is not None:
        tblW.set(qn('w:type'), 'dxa')
        tblW.set(qn('w:w'), str(int(sum(widths) * 1440)))'''
assert old in s
s = s.replace(old, new)
open(p,'w').write(s); print('patched set_widths')
